#include <stdio.h>
typedef struct Node {
    int val;
    struct Node* next;
} Node;
Node* reverse(Node* head) {
    Node *prev=NULL, *curr=head, *nxt;
    while (curr) {
        nxt=curr->next;
        curr->next=prev;
        prev=curr;
        curr=nxt;
    }
    return prev;
}

